export const IVUS_FIND={ivus:{ref:tr('正常參考段：血管壁可見「三層結構」——較亮的內膜、暗的中膜、亮的外膜；中膜外緣就是外彈性膜（EEM）。管腔內細細的斑點是血液的回音。'),
ca:tr('瀰漫鈣化：鈣化表面極亮，後方完全被遮住（聲影），看不到鈣化厚度，也看不到後方的血管外緣。鈣化弧越大、越接近整圈，支架越不容易撐開。'),
soft:tr('軟斑塊（纖維脂肪斑塊）：偏心、回音比外膜暗的低回音斑塊，後方沒有聲影；斑塊負荷高，但管腔還不算太窄。'),
tcfa:tr('易破裂斑塊：大片低回音斑塊、深處訊號逐漸衰減（attenuated plaque），血管往外撐大（正向重塑）。IVUS 解析度不足以量到薄纖維帽，要靠 OCT。'),
stent:tr('支架段：每根支架鋼絲是一個亮點、後方有陰影。中段被鈣化擋住，支架擴張不足（MSA ÷ 參考管腔面積 < 80%）；近端邊緣鋼絲和血管壁之間有血流空隙，是貼壁不良。'),
diss:tr('支架遠端邊緣剝離：一片內膜撕開翹進管腔（flap），後方是假腔的血流。要評估剝離的角度、長度、深度，決定是否需要再放一支支架。')},
oct:{ref:tr('正常參考段：OCT 可清楚分出內膜（亮）、中膜（暗帶）、外膜三層，組織訊號均勻；管腔因顯影劑沖洗而全黑。'),
ca:tr('瀰漫鈣化：OCT 中的鈣化是邊界銳利、訊號偏暗的區塊；光可以穿過鈣化，所以量得到厚度。鈣化弧＞180°、厚度＞0.5 mm、長度＞5 mm 時支架容易擴張不足，應先考慮旋磨或震波碎石。'),
soft:tr('軟斑塊（纖維脂肪斑塊）：訊號中等、較不均勻的偏心斑塊；深處訊號較快衰減，所以通常看不到外彈性膜。'),
tcfa:tr('易破裂斑塊（TCFA）：亮而薄的纖維帽（＜65 µm）覆蓋大片訊號暗、邊界模糊的脂質核心，帽下亮點是巨噬細胞堆積；脂質弧＞90°。這是日後斑塊破裂、急性心肌梗塞的高風險病灶。'),
stent:tr('支架段：每根鋼絲是一條亮線、後方全黑陰影，可以逐根判斷貼壁。中段被鈣化擋住擴張不足；近端邊緣鋼絲離開血管壁，貼壁不良距離＞0.4 mm 時較有臨床意義。'),
diss:tr('支架遠端邊緣剝離：OCT 清楚看到撕開翹起的內膜片（flap）和後方的假腔，可以量出剝離的弧度與深度。')}};
